Your Options


apply = Generators.input(document.getElementById("apply_button"))







filtered = { apply;
if (!data || !Array.isArray(data)) return [];
return data.filter(g =&gt; {
  if (document.getElementById("duration_count").checked && g.endurance_days != null && g.endurance_days &lt; Number(document.getElementById("duration_slider").value)) return false
  if (document.getElementById("depth_count").checked && g.max_depth_m != null && g.max_depth_m &lt; Number(document.getElementById("depth_slider").value)) return false
  if (document.getElementById("speed_count").checked && g.speed_kt != null && g.speed_kt &lt; Number(document.getElementById("speed_slider").value)) return false
  if (document.getElementById("mass_count").checked && g.mass_kg != null && g.mass_kg &gt; Number(document.getElementById("mass_slider").value)) return false
  if (document.getElementById("ice_checkbox").checked && g.ice_capable !== true && g.ice_capable !== "yes") return false
  if (document.getElementById("rt_checkbox").checked && g.real_time_comms !== "yes") return false

  return true;
});
}
  // Add these back when the spreadsheet has the corresponding columns:
  // if (document.getElementById("range_count").checked && g.range_km != null && g.range_km &lt; Number(document.getElementById("range_slider").value)) return false
