Inputs.table(filtered, {
  columns: [
    "manufacturer", "glider", "max_depth_m", "endurance_days",
    "speed_kt", "mass_kg", "real_time_comms", "acoustic_sensor", "ice_capable"
  ],
  header: {
    manufacturer: "Manufacturer",
    glider: "Glider",
    max_depth_m: "Max depth (m)",
    endurance_days: "Endurance (days, est.)",
    speed_kt: "Speed (kt, est.)",
    mass_kg: "Mass (kg)",
    real_time_comms: "Real-time comms",
    acoustic_sensor: "Acoustic sensor",
    ice_capable: "Ice capable"
  }
})
